import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"operations/configuration.md","filePath":"operations/configuration.md","lastUpdated":1788529216000}'),i={name:"operations/configuration.md"};function r(d,e,s,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Chart defaults are documented in <code>deploy/helm/aegisscan/values.yaml</code>. Runtime settings are validated by the API and include concurrency, default scan mode, retention, and cache limits. Use Kubernetes Secret references for Git provider, database, scanner, and OIDC credentials.</p><p>Full scans require explicit operator/admin intent and should be scheduled with the retention and concurrency limits appropriate for the repository set.</p><p>For production OIDC, set <code>AEGIS_OIDC_ISSUER</code>, <code>AEGIS_OIDC_AUDIENCE</code>, <code>AEGIS_OIDC_ROLE_CLAIM</code>, and <code>AEGIS_OIDC_JWKS_URL</code> together. The API then requires bearer authentication and validates issuer, audience, signature, and mapped role claims. <code>AEGIS_ALLOW_ROLE_HEADER=true</code> is a local-development-only compatibility switch and should not be enabled in production. <code>AEGIS_ALLOW_DEMO_DATA=true</code> is limited to the Compose/demo profile and seeds three sample repositories, completed TruffleHog runs, and open findings for smoke testing. The default Compose URLs point to the <code>Jasonrve</code> forks. Set <code>AEGIS_DEMO_REPOSITORY_URLS</code> to a comma-separated list of other fork clone URLs to change the targets for Renovate issue and pull-request tests. The seed is idempotent and runs after database migrations. <code>AEGIS_OIDC_ROLE_MAPPINGS</code> may contain a JSON object mapping IdP group names to <code>admin</code>, <code>operator</code>, or <code>viewer</code>. Set <code>AEGIS_SCAN_WEBHOOK_URL</code> to receive a sanitized <code>scan.completed</code> JSON payload after a Kubernetes-backed execution reaches a terminal state. Set <code>AEGIS_REPORT_DIRECTORY</code> to a writable directory to emit daily timestamped CSV and PDF findings reports from the maintenance worker. Optionally set <code>AEGIS_API_IP_ALLOWLIST</code> to a comma-separated list of IPs or CIDRs to restrict API traffic.</p><h2 id="database-pool-sizing" tabindex="-1">Database pool sizing <a class="header-anchor" href="#database-pool-sizing" aria-label="Permalink to &quot;Database pool sizing&quot;">​</a></h2><p>Each API pod defaults to 20 open and 5 idle PostgreSQL connections, with a 30-minute maximum connection lifetime. Set <code>AEGIS_DB_MAX_OPEN_CONNS</code> and <code>AEGIS_DB_MAX_IDLE_CONNS</code> per pod so the sum across replicas stays below the PostgreSQL connection budget (leave capacity for migrations, operators, and administrative tools). Startup fails if the database cannot be reached or migrations cannot be applied.</p>',6)])])}const m=o(i,[["render",r]]);export{u as __pageData,m as default};
